<div class="intro-line"><p>Rencana pemeriksaan, temuan, dan tindak lanjut tersimpan dalam satu riwayat. Penilaian kesehatan yang telah dikunci dapat ditautkan sebagai bahan pemeriksaan.</p><?php if ($can_create): ?><a class="button button-dark" href="<?= site_url('admin/pengawasan/tambah') ?>">+ Rencanakan pemeriksaan</a><?php endif; ?></div>
<section class="panel table-panel"><form class="filterbar" method="get" action="<?= site_url($path) ?>"><label class="search-field"><span>Cari pemeriksaan</span><input type="search" name="q" value="<?= h($p['q']) ?>" placeholder="Nama, NIK, nomor tugas"></label><label><span>Status</span><select name="status"><option value="">Semua</option><?php foreach ($statuses as $code=>$name): ?><option value="<?= h($code) ?>" <?= $p['status']===$code?'selected':'' ?>><?= h($name) ?></option><?php endforeach; ?></select></label><label><span>Per halaman</span><select name="per_page"><?php foreach (array(10,25,50,100) as $n): ?><option value="<?= $n ?>" <?= $p['per_page']===$n?'selected':'' ?>><?= $n ?></option><?php endforeach; ?></select></label><button class="button button-dark button-small">Terapkan</button><a class="button button-quiet button-small" href="<?= site_url($path) ?>">Reset</a></form><div class="table-wrap"><table><thead><tr><th>Koperasi</th><th>Nomor tugas</th><th>Jenis</th><th>Petugas</th><th>Tanggal</th><th>Status</th><th>Aksi</th></tr></thead><tbody><?php foreach ($rows as $r): ?><tr><td><strong><?= h($r['cooperative_name']) ?></strong></td><td><?= h($r['assignment_number']?:'—') ?></td><td><?= $r['inspection_type']==='routine'?'Rutin':'Insidental' ?></td><td><?= h($r['lead_name']?:'Belum ditugaskan') ?></td><td><?= $r['started_on']?h(date('d M Y',strtotime($r['started_on']))):'—' ?></td><td><span class="pill <?= $r['status']==='completed'?'pill-green':'pill-blue' ?>"><?= h($statuses[$r['status']]??$r['status']) ?></span></td><td><a class="row-link" href="<?= site_url('admin/pengawasan/'.$r['id']) ?>">Buka →</a></td></tr><?php endforeach; ?><?php if (!$rows): ?><tr><td colspan="7" class="empty-cell">Belum ada pemeriksaan yang sesuai filter.</td></tr><?php endif; ?></tbody></table></div><?php $this->load->view('partials/pagination'); ?></section>
